<section class="ms-swind">
    <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.css">

    <style>
        .ms-swind,
        .ms-swind * {
            box-sizing: border-box;
        }

        .ms-swind {
            --purple: #5A2EA6;
            width: 100%;
            padding: 60px 20px 70px;
            background: #fff;
            font-family: var(--font-body);
        }

        .ms-swind-wrap {
            max-width: 1110px;
            margin: 0 auto;
        }

        /* ---------- Heading ---------- */
        .ms-swind-title {
            margin: 0 0 18px;
            text-align: center;
            font-size: 44px;
            line-height: 1.2;
            font-weight: 600;
            color: #000;
        }

        .ms-swind-title span {
            color: var(--purple);
        }

        .ms-swind-intro {
            margin: 0 auto 50px;
            max-width: 900px;
            text-align: center;
            font-size: 15px;
            line-height: 1.75;
            font-weight: 400;
            color: #222;
        }

        /* ---------- Carousel (arrows sit outside the slides) ---------- */
        .ms-swind-carousel {
            position: relative;
            padding: 0 60px;
        }

        .ms-swind .swiper {
            padding: 8px 4px 14px; /* room for hover lift + shadow */
        }

        .ms-swind .swiper-slide {
            height: auto;
        }

        .ms-swind-card {
            height: 100%;
            padding: 34px 28px 36px;
            border-radius: 24px;
            border: 1px solid #ececec;
            background: #f6f6f6;
            text-align: center;
            transition: .3s ease;
        }

        .ms-swind-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 12px 28px rgba(90, 46, 166, .16);
        }

        .ms-swind-icon {
            width: 62px;
            height: 62px;
            margin: 0 auto 18px;
            border-radius: 50%;
            border: 1px solid #111;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .ms-swind-icon svg {
            width: 28px;
            height: 28px;
            fill: #111;
        }

        .ms-swind-card h3 {
            margin: 0 0 14px;
            font-size: 20px;
            line-height: 1.35;
            font-weight: 600;
            color: #000;
        }

        .ms-swind-card p {
            margin: 0;
            font-size: 14px;
            line-height: 1.8;
            font-weight: 400;
            color: #222;
        }

        .ms-swind-arrow {
            position: absolute;
            top: 50%;
            width: 44px;
            height: 44px;
            margin-top: -22px;
            padding: 0;
            border: 1px solid var(--purple);
            border-radius: 50%;
            background: #fff;
            color: var(--purple);
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: .25s ease;
            z-index: 2;
        }

        .ms-swind-arrow svg {
            width: 14px;
            height: 14px;
            fill: currentColor;
        }

        .ms-swind-arrow:hover {
            background: var(--purple);
            color: #fff;
        }

        .ms-swind-arrow:focus-visible {
            outline: 2px solid var(--purple);
            outline-offset: 2px;
        }

        .ms-swind-prev { left: 0; }
        .ms-swind-next { right: 0; }

        /* ---------- Tablet ---------- */
        @media (max-width: 991px) {
            .ms-swind-title {
                font-size: 36px;
            }

            .ms-swind-carousel {
                padding: 0 54px;
            }

            .ms-swind-card {
                padding: 30px 20px 32px;
            }

            .ms-swind-card h3 {
                font-size: 18px;
            }
        }

        /* ---------- Mobile: one slide at a time ---------- */
        @media (max-width: 767px) {
