    <script src="https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.js"></script>
    <script>
        (function() {
            if (typeof Swiper === 'undefined') return;

            // same settings as the Elementor carousel: 3 slides (1 on mobile), 10px gap,
            // loop, 700ms slide speed, autoplay every 2 seconds
            new Swiper('.ms-swind-swiper', {
                slidesPerView: 1,
                spaceBetween: 10,
                loop: true,
                speed: 700,
                autoplay: {
                    delay: 2000,
                    disableOnInteraction: false,
                    pauseOnMouseEnter: true
                },
                navigation: {
                    prevEl: '.ms-swind-prev',
                    nextEl: '.ms-swind-next'
                },
                breakpoints: {
                    768: { slidesPerView: 3 }
                }
            });
        })();
    </script>
